import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        t = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(t):
        try:
            x_str = next(iterator)
            x = int(x_str)
        except StopIteration:
            break

        if x % 2 != 0:
            results.append("-1")
            continue

        k = x // 2
        if k == 0:
            results.append("-1")
            continue

        a = x | k
        b = k

        if (a ^ b) == x and (a + b) // 2 == x and a > 0 and b > 0:
            results.append(f"{a} {b}")
        else:
            results.append("-1")

    print('\n'.join(results))

if __name__ == '__main__':
    solve()
